int okumalar[] = {420, 310, 760, 690, 240};

void setup() {
  Serial.begin(9600);
  int enAz = 1023, enCok = 0;
  for (int i = 0; i < 5; i++) {
    if (okumalar[i] < enAz) enAz = okumalar[i];
    if (okumalar[i] > enCok) enCok = okumalar[i];
  }
  int esik = (enAz + enCok) / 2;
  Serial.print(esik);
  Serial.print(' ');
  Serial.println(500 > esik);
}
void loop() {}
